--! platoboost library

local Platoboost = {}

local cloneref = (cloneref or clonereference or function(instance) return instance end)


function Platoboost.New(Service, Secret)
    --! configuration
    local service = Service;  -- your service id, this is used to identify your service.
    local secret = Secret;  -- make sure to obfuscate this if you want to ensure security.
    local useNonce = true;  -- use a nonce to prevent replay attacks and request tampering.
    
    --! callbacks
    local onMessage = function(message) end;
    
    --! wait for game to load
    repeat task.wait(1) until game:IsLoaded();
    
    --! functions
    local requestSending = false;
    local fSetClipboard, fRequest, fStringChar, fToString, fStringSub, fOsTime, fMathRandom, fMathFloor, fGetHwid = setclipboard or toclipboard, request or http_request or syn_request, string.char, tostring, string.sub, os.time, math.random, math.floor, gethwid or function() return cloneref(game:GetService("Players")).LocalPlayer.UserId end
    local cachedLink, cachedTime = "", 0;
    
    --! pick host
    local host = "https://api.platoboost.app";
    local hostResponse = fRequest({
        Url = host .. "/public/connectivity",
        Method = "GET"
    });
    if hostResponse.StatusCode ~= 200 and hostResponse.StatusCode ~= 429 then
        host = "https://api.platoboost.net";
    end
    
    --!optimize 2
    function cacheLink()
        if cachedTime + (10*60) < fOsTime() then
            local response = fRequest({
                Url = host .. "/public/start",
                Method = "POST",
                Body = lEncode({
                    service = service,
                    identifier = lDigest(fGetHwid())
                }),
                Headers = {
                    ["Content-Type"] = "application/json",
                    ["User-Agent"] = "Roblox/Exploit"
                }
            });
    
            if response.StatusCode == 200 then
                local decoded = lDecode(response.Body);
    
                if decoded.success == true then
                    cachedLink = decoded.data.url;
                    cachedTime = fOsTime();
                    return true, cachedLink;
                else
                    onMessage(decoded.message);
                    return false, decoded.message;
                end
            elseif response.StatusCode == 429 then
                local msg = "you are being rate limited, please wait 20 seconds and try again.";
                onMessage(msg);
                return false, msg;
            end
    
            local msg = "Failed to cache link.";
            onMessage(msg);
            return false, msg;
        else
            return true, cachedLink;
        end
    end
    
    cacheLink();
    
    --!optimize 2
    local generateNonce = function()
        local str = ""
        for _ = 1, 16 do
            str = str .. fStringChar(fMathFloor(fMathRandom() * (122 - 97 + 1)) + 97)
        end
        return str
    end
    
    --!optimize 1
    for _ = 1, 5 do
        local oNonce = generateNonce();
        task.wait(0.2)
        if generateNonce() == oNonce then
            local msg = "platoboost nonce error.";
            onMessage(msg);
            error(msg);
        end
    end
    
    --!optimize 2
    local copyLink = function()
        local success, link = cacheLink();
        
        if success then
            fSetClipboard(link);
        end
    end
    
    --!optimize 2
    local redeemKey = function(key)
        local nonce = generateNonce();
        local endpoint = host .. "/public/redeem/" .. fToString(service);
    
        local body = {
            identifier = lDigest(fGetHwid()),
            key = key
        }
    
        if useNonce then
            body.nonce = nonce;
        end
    
        local response = fRequest({
            Url = endpoint,
            Method = "POST",
            Body = lEncode(body),
            Headers = {
                ["Content-Type"] = "application/json"
            }
        });
    
        if response.StatusCode == 200 then
            local decoded = lDecode(response.Body);
    
            if decoded.success == true then
                if decoded.data.valid == true then
                    if useNonce then
                        if decoded.data.hash == lDigest("true" .. "-" .. nonce .. "-" .. secret) then
                            return true;
                        else
                            onMessage("failed to verify integrity.");
                            return false;
                        end    
                    else
                        return true;
                    end
                else
                    onMessage("key is invalid.");
                    return false;
                end
            else
                if fStringSub(decoded.message, 1, 27) == "unique constraint violation" then
                    onMessage("you already have an active key, please wait for it to expire before redeeming it.");
                    return false;
                else
                    onMessage(decoded.message);
                    return false;
                end
            end
        elseif response.StatusCode == 429 then
            onMessage("you are being rate limited, please wait 20 seconds and try again.");
            return false;
        else
            onMessage("server returned an invalid status code, please try again later.");
            return false; 
        end
    end
    
    --!optimize 2
    local verifyKey = function(key)
        if requestSending == true then
            return false, ("A request is already being sent, please slow down.");
        else
            requestSending = true;
        end
    
        local nonce = generateNonce();
        local endpoint = host .. "/public/whitelist/" .. fToString(service) .. "?identifier=" .. lDigest(fGetHwid()) .. "&key=" .. key;
    
        if useNonce then
            endpoint = endpoint .. "&nonce=" .. nonce;
        end
    
        local response = fRequest({
            Url = endpoint,
            Method = "GET",
        });
    
        requestSending = false;
    
        if response.StatusCode == 200 then
            local decoded = lDecode(response.Body);
    
            if decoded.success == true then
                if decoded.data.valid == true then
                    if useNonce then
                        if decoded.data.hash == lDigest("true" .. "-" .. nonce .. "-" .. secret) then
                            return true, "";
                        else
                            return false, ("failed to verify integrity.");
                        end
                    else
                        return true;
                    end
                else
                    if fStringSub(key, 1, 4) == "KEY_" then
                        return true, redeemKey(key);
                    else
                        return false, ("Key is invalid.");
                    end
                end
            else
                return false, (decoded.message);
            end
        elseif response.StatusCode == 429 then
            return false, ("You are being rate limited, please wait 20 seconds and try again.");
        else
            return false, ("Server returned an invalid status code, please try again later.");
        end
    end
    
    --!optimize 2
    local getFlag = function(name)
        local nonce = generateNonce();
        local endpoint = host .. "/public/flag/" .. fToString(service) .. "?name=" .. name;
    
        if useNonce then
            endpoint = endpoint .. "&nonce=" .. nonce;
        end
    
        local response = fRequest({
            Url = endpoint,
            Method = "GET",
        });
    
        if response.StatusCode == 200 then
            local decoded = lDecode(response.Body);
    
            if decoded.success == true then
                if useNonce then
                    if decoded.data.hash == lDigest(fToString(decoded.data.value) .. "-" .. nonce .. "-" .. secret) then
                        return decoded.data.value;
                    else
                        onMessage("failed to verify integrity.");
                        return nil;
                    end
                else
                    return decoded.data.value;
                end
            else
                onMessage(decoded.message);
                return nil;
            end
        else
            return nil;
        end
    end
    
    
    return {
        Verify = verifyKey,
        GetFlag = getFlag,
        Copy = copyLink,
    }
end


return Platoboost
end

return __bundle_require('src/Init.lua')
